      "id": "p-217",
      "sectionId": "act-1",
      "fr": "STELLA (intervenant avec une lucidité tranchante) : Parce qu'Amédée exige de la créature ce que seul l'Incréé pourrait lui donner. Il traite les êtres vivants comme des réservoirs qu'il vide avant de les briser. (Le diagnostic de l'indigence spirituelle — réplique 217)",
      "en": "STELLA (intervening with piercing lucidity): Because Amédée demands from the creature what only the Uncreated could bestow. He treats living beings as vessels that he drains before shattering them. (Diagnosis of Spiritual Destitution — line 217)"
