      "fr": "ÉVELYNE (se plaçant entre Amédée et Stella) : Laissez-le en paix ! Vous vous acharnez sur ses blessures comme des juges sans entrailles. Si la foi et l'amour existent, ils ne se découvrent pas dans vos réquisitoires. (Le pressentiment de la grâce au cœur de l'épreuve — réplique 381)",
