      "fr": "STELLA (apparaissant sur le perron, tenant un livre d'art) : La nature n'est qu'un miroir passif où nous projetons nos névroses, Amédée. Ce silence que tu cherches n'est que la peur panique de ton impuissance. (La retraite de campagne : L'illusion du silence — réplique 627)",
      "en": "STELLA (appearing on the terrace steps, holding an art book): Nature is merely a passive mirror upon which we project our neuroses, Amédée. That silence you seek is merely the panic fear of your impotence. (The Country Retreat: Illusion of Silence — line 627)"
